<template>
  <div>
    <div class="page-heading page-heading-actions"><div><h1>Organizations</h1><p>Manage university partnership organizations.</p></div><button class="primary" @click="openCreate">+ Add Organization</button></div>
    <div class="filters"><input v-model="search" placeholder="Search by name..."><select v-model="type"><option value="">All types</option><option v-for="(label,key) in typeLabels" :key="key" :value="key">{{ label }}</option></select><select v-model="academicUnit"><option value="">All Directions</option><option v-for="unit in academicUnits" :key="unit.id" :value="String(unit.id)">{{ unit.name }}</option></select></div>
    <p v-if="loading">Loading organizations...</p><p v-else-if="error" class="error">{{ error }}</p><p v-else-if="filtered.length===0" class="empty">No organizations found.</p>
    <div v-else class="table-wrap"><table><thead><tr><th>Name</th><th>Type</th><th>Country</th><th>Website</th><th>Directions</th><th class="actions-column">Actions</th></tr></thead><tbody><tr v-for="org in filtered" :key="org.id"><td><RouterLink :to="`/organizations/${org.id}`">{{ org.name }}</RouterLink></td><td>{{ typeLabels[org.organization_type]||org.organization_type }}</td><td>{{ org.country||'—' }}</td><td><a v-if="org.website" :href="org.website" target="_blank" rel="noopener">{{ org.website }}</a><span v-else>—</span></td><td><div v-if="org.academic_units?.length" class="unit-tags"><span v-for="unit in org.academic_units" :key="unit.id" class="unit-tag">{{ unit.name }}</span></div><span v-else>—</span></td><td class="actions-cell"><ActionMenu v-if="canManage(org)" @edit="openEdit(org)" @delete="openDelete(org)" /></td></tr></tbody></table></div>
    <div v-if="showForm" class="modal-backdrop" @click.self="closeForm"><div class="modal-card"><div class="modal-header"><div><h2>{{ editingOrganization?'Edit Organization':'Add Organization' }}</h2><p>{{ editingOrganization?'Update organization information.':'Create a new partner organization.' }}</p></div><button type="button" class="modal-close" @click="closeForm">×</button></div><form class="organization-form" @submit.prevent="saveOrganization"><label>Name<input v-model="form.name" required></label><label>Type<select v-model="form.organization_type" required><option value="" disabled>Select type</option><option v-for="(label,key) in typeLabels" :key="key" :value="key">{{ label }}</option></select></label><label>Country<input v-model="form.country" required></label><label>Website<input v-model="form.website" type="url" placeholder="https://..."></label><label class="full-width">Description<textarea v-model="form.description" rows="4" /></label><fieldset class="full-width unit-selection"><legend>Directions</legend><p v-if="!availableUnits.length" class="muted">No directions available.</p><button v-for="unit in availableUnits" :key="unit.id" type="button" class="direction-tile" :class="{'is-selected':form.academic_unit_ids.includes(unit.id)}" :aria-pressed="form.academic_unit_ids.includes(unit.id)" @click="toggleUnit(unit.id)"><span aria-hidden="true">{{ form.academic_unit_ids.includes(unit.id)?'✓':'' }}</span>{{ unit.name }}<small v-if="!unit.is_active"> (Inactive; existing relationship)</small></button></fieldset><label class="checkbox full-width"><input v-model="form.is_public" type="checkbox">Public organization</label><div v-if="formError" class="error full-width">{{ formError }}</div><div class="modal-actions full-width"><button type="button" @click="closeForm">Cancel</button><button class="primary" :disabled="submitting">{{ submitting?'Saving...':editingOrganization?'Save changes':'Create Organization' }}</button></div></form></div></div>
    <ConfirmDialog :open="!!organizationToDelete" :busy="deleting" title="Delete organization?" :message="organizationToDelete ? `${organizationToDelete.name} and its related agreements will be deleted.` : ''" @cancel="cancelDelete" @confirm="deleteOrganization" />
    <p v-if="deleteError" class="error">{{ deleteError }}</p>
  </div>
</template>
<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import client from '../api/client'
import { useAuthStore } from '../stores/auth'
import ActionMenu from '../components/ActionMenu.vue'
import ConfirmDialog from '../components/ConfirmDialog.vue'
import { ORGANIZATION_TYPE_LABELS } from '../constants/partnerships'
const auth=useAuthStore(),organizations=ref([]),academicUnits=ref([]),loading=ref(true),error=ref(''),search=ref(''),type=ref(''),academicUnit=ref(''),showForm=ref(false),editingOrganization=ref(null),submitting=ref(false),formError=ref(''),organizationToDelete=ref(null),deleting=ref(false),deleteError=ref('')
const typeLabels=ORGANIZATION_TYPE_LABELS,blankForm=()=>({name:'',organization_type:'',country:'',website:'',description:'',is_public:false,academic_unit_ids:[]}),form=ref(blankForm())
const availableUnits=computed(()=>{const linked=new Set((editingOrganization.value?.academic_units||[]).map(unit=>unit.id));return academicUnits.value.filter(unit=>unit.is_active||linked.has(unit.id))})
const filtered=computed(()=>organizations.value.filter(org=>(!search.value||org.name.toLowerCase().includes(search.value.toLowerCase()))&&(!type.value||org.organization_type===type.value)))
function canManage(org){return Boolean(auth.user?.is_superuser||(auth.user?.id&&Number(org.created_by)===Number(auth.user.id)))}
function toggleUnit(id){const ids=form.value.academic_unit_ids;form.value.academic_unit_ids=ids.includes(id)?ids.filter(value=>value!==id):[...ids,id]}
async function loadOrganizations(){loading.value=true;error.value='';try{const {data}=await client.get('/api/organizations/',{params:academicUnit.value?{academic_unit:academicUnit.value}:{}});organizations.value=Array.isArray(data)?data:data.results||[]}catch{error.value='Unable to load organizations.'}finally{loading.value=false}}
async function loadUnits(){try{const {data}=await client.get('/api/academic-units/');academicUnits.value=(Array.isArray(data)?data:data.results||[])}catch{academicUnits.value=[]}}
function openCreate(){editingOrganization.value=null;form.value=blankForm();formError.value='';showForm.value=true}
function openEdit(org){editingOrganization.value=org;form.value={name:org.name||'',organization_type:org.organization_type||'',country:org.country||'',website:org.website||'',description:org.description||'',is_public:Boolean(org.is_public),academic_unit_ids:(org.academic_units||[]).map(unit=>unit.id)};formError.value='';showForm.value=true}
function closeForm(force=false){if(submitting.value&&!force)return;showForm.value=false;editingOrganization.value=null;form.value=blankForm();formError.value=''}
function apiErrorMessage(err){if(err.response?.status===403)return 'You do not have permission to perform this action.';const data=err.response?.data;if(data&&typeof data==='object'){const messages=Object.entries(data).map(([field,value])=>`${field}: ${Array.isArray(value)?value.join(', '):String(value)}`);if(messages.length)return messages.join(' ')}return 'Unable to save organization.'}
async function saveOrganization(){if(submitting.value)return;submitting.value=true;formError.value='';try{const payload={...form.value,website:form.value.website.trim(),academic_unit_ids:form.value.academic_unit_ids.map(Number)};if(editingOrganization.value)await client.patch(`/api/organizations/${editingOrganization.value.id}/`,payload);else await client.post('/api/organizations/',payload);closeForm(true);await loadOrganizations()}catch(err){formError.value=apiErrorMessage(err)}finally{submitting.value=false}}
function openDelete(org){organizationToDelete.value=org;deleteError.value=''}function cancelDelete(){if(deleting.value)return;organizationToDelete.value=null;deleteError.value=''}
async function deleteOrganization(){if(deleting.value||!organizationToDelete.value)return;deleting.value=true;deleteError.value='';try{await client.delete(`/api/organizations/${organizationToDelete.value.id}/`);organizationToDelete.value=null;await loadOrganizations()}catch(err){deleteError.value=err.response?.status===403?'You do not have permission to perform this action.':'Unable to delete organization.'}finally{deleting.value=false}}
watch(academicUnit,loadOrganizations)
onMounted(async()=>{try{await auth.loadCurrentUser()}catch{}await Promise.all([loadUnits(),loadOrganizations()])})
</script>
